# Study v_2(u_n - 1) for Family A
# Family A: u_0=1, u_1=11, u_{n+1}=6*u_n - u_{n-1}

def gen_family(u0, u1, N):
    seq = [u0, u1]
    for i in range(2, N):
        seq.append(6*seq[-1] - seq[-2])
    return seq

famA = gen_family(1, 11, 60)

def v2(n):
    if n == 0:
        return float('inf')
    v = 0
    while n % 2 == 0:
        n //= 2
        v += 1
    return v

print("Family A: v_2(u_n - 1) for even n")
for n in range(0, 40, 2):
    u = famA[n]
    val = v2(u - 1) if u > 1 else 'inf'
    print(f"  n={n}: u={u}, u-1={u-1}, v_2(u-1)={val}")

print("\nFamily A: v_2(u_n - 1) for odd n")
for n in range(1, 20, 2):
    u = famA[n]
    val = v2(u - 1)
    print(f"  n={n}: u={u}, u-1={u-1}, v_2(u-1)={val}")
EOF

