# Study v_2(u_{2m} - 1) for Family A more carefully
# Also look at the subsequence v_m = u_{2m} with recurrence v_{m+1} = 34*v_m - v_{m-1}

def gen_family(u0, u1, N):
    seq = [u0, u1]
    for i in range(2, N):
        seq.append(6*seq[-1] - seq[-2])
    return seq

def v2(n):
    if n == 0:
        return float('inf')
    v = 0
    while n % 2 == 0:
        n //= 2
        v += 1
    return v

famA = gen_family(1, 11, 120)

# v_m = u_{2m}
v_seq = [famA[2*m] for m in range(60)]

